38	func (b *binder) bindResource(ctx context.Context, node *Resource) hcl.Diagnostics {
39		var diagnostics hcl.Diagnostics
40	
41		typeDiags := b.bindResourceTypes(ctx, node)
42		diagnostics = append(diagnostics, typeDiags...)
43	
44		bodyDiags := b.bindResourceBody(node)
45		diagnostics = append(diagnostics, bodyDiags...)
46	
47		return diagnostics
48	}
