// hookReferenceName returns the name of the hook referenced by the given expression. Hook references are scope
// traversals whose root name is the hook name (e.g. `foo` in `hooks = { beforeCreate = [foo] }`).
func hookReferenceName(expr model.Expression) string {
	if traversal, ok := expr.(*model.ScopeTraversalExpression); ok {
		return traversal.RootName
	}
	if value, ok := literalExprValue(expr); ok && value.Type().Equals(cty.String) {
