// bindResourceHooks binds the 'hooks' resource option. The option must be an object that maps lifecycle event names
// to lists of hook references. The returned expression, when evaluated with an empty context, produces a cty object
// where each key is a lifecycle event name and each value is a tuple of hook name strings.
func bindResourceHooks(expr model.Expression) (model.Expression, hcl.Diagnostics) {
	var diagnostics hcl.Diagnostics

	hooksError := func(rng hcl.Range) *hcl.Diagnostic {
		return errorf(rng, "hooks option must be an object mapping hook names to lists of hook references")
	}

	object, ok := expr.(*model.ObjectConsExpression)
	if !ok {
		return expr, hcl.Diagnostics{hooksError(expr.SyntaxNode().Range())}
	}

	items := make([]model.ObjectConsItem, 0, len(object.Items))
	for _, item := range object.Items {
		key, ok := literalExprValue(item.Key)
		if !ok || !key.Type().Equals(cty.String) {
			diagnostics = append(diagnostics, hooksError(item.Key.SyntaxNode().Range()))
			continue
		}

		eventName := key.AsString()
		if !validHookEvents[eventName] {
			diagnostics = append(diagnostics, errorf(item.Key.SyntaxNode().Range(), "unknown hook name '%s'", eventName))
			continue
		}

		tuple, ok := item.Value.(*model.TupleConsExpression)
		if !ok {
			diagnostics = append(diagnostics, hooksError(item.Value.SyntaxNode().Range()))
			continue
		}

		hookRefs := make([]model.Expression, 0, len(tuple.Expressions))
		for _, refExpr := range tuple.Expressions {
			hookRefs = append(hookRefs, &model.LiteralValueExpression{
				Value: cty.StringVal(hookReferenceName(refExpr)),
			})
		}

		items = append(items, model.ObjectConsItem{
			Key:   &model.LiteralValueExpression{Value: cty.StringVal(eventName)},
			Value: &model.TupleConsExpression{Expressions: hookRefs},
		})
	}

	return &model.ObjectConsExpression{Items: items}, diagnostics
}

