func TestScratchHookBasic(t *testing.T) {
	src := `
hook "foo" {
    command = ["echo", "hi", true, 42]
    onDryRun = false
}
`
	program, diags, err := ParseAndBindProgram(t, src, "scratch.pp", pcl.SkipResourceTypechecking)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if diags.HasErrors() {
		t.Fatalf("unexpected diags: %v", diags)
	}
	hooks := program.Hooks()
	if len(hooks) != 1 {
		t.Fatalf("expected 1 hook, got %d", len(hooks))
	}
	if hooks[0].Name() != "foo" {
		t.Fatalf("expected name foo, got %s", hooks[0].Name())
	}
	t.Logf("OK basic")
}

