func TestScratchResourceHooks(t *testing.T) {
	src := `
hook "foo" {
    command = ["echo"]
}

resource "res" "test:index:Res" {
    options {
        hooks = {
            beforeCreate = [foo]
        }
    }
}
`
	program, diags, _ := ParseAndBindProgram(t, src, "scratch.pp", pcl.SkipResourceTypechecking)
	for _, d := range diags {
		t.Logf("diag: %q sev=%v", d.Summary, d.Severity)
	}
	var res *pcl.Resource
	for _, n := range program.Nodes {
		if r, ok := n.(*pcl.Resource); ok {
			res = r
		}
	}
	if res == nil {
		t.Fatalf("no resource")
	}
	if res.Options == nil || res.Options.Hooks == nil {
		t.Fatalf("hooks not set")
	}
	v, vdiags := res.Options.Hooks.Evaluate(&hcl.EvalContext{})
	if vdiags.HasErrors() {
		t.Fatalf("eval err: %v", vdiags)
	}
	expected := cty.ObjectVal(map[string]cty.Value{
		"beforeCreate": cty.TupleVal([]cty.Value{cty.StringVal("foo")}),
	})
	if !v.RawEquals(expected) {
		t.Fatalf("got %#v want %#v", v, expected)
	}
	t.Logf("OK resource hooks eval")
}

